-- Bilingual (ca/es) shopping catalog. Rows with household_id NULL are the shared seed
-- (stable ids, read-only); households add their own categories/products on demand.
CREATE TABLE shopping_category (
    id           CHAR(36) NOT NULL PRIMARY KEY,
    household_id CHAR(36),
    code         VARCHAR(64),
    name_ca      VARCHAR(100) NOT NULL,
    name_es      VARCHAR(100) NOT NULL,
    sort_order   INTEGER NOT NULL DEFAULT 1000,
    CONSTRAINT fk_shopping_category_household FOREIGN KEY (household_id) REFERENCES household(id)
);
CREATE INDEX idx_shopping_category_household ON shopping_category(household_id);

CREATE TABLE shopping_product (
    id           CHAR(36) NOT NULL PRIMARY KEY,
    household_id CHAR(36),
    category_id  CHAR(36),
    name_ca      VARCHAR(255) NOT NULL,
    name_es      VARCHAR(255) NOT NULL,
    translated   BOOLEAN NOT NULL DEFAULT TRUE,
    CONSTRAINT fk_shopping_product_household FOREIGN KEY (household_id) REFERENCES household(id),
    CONSTRAINT fk_shopping_product_category FOREIGN KEY (category_id) REFERENCES shopping_category(id)
);
CREATE INDEX idx_shopping_product_household ON shopping_product(household_id);

ALTER TABLE shopping_item ADD COLUMN product_id CHAR(36) REFERENCES shopping_product(id);
ALTER TABLE shopping_item ADD COLUMN category_id CHAR(36) REFERENCES shopping_category(id);


